</head>
<body>

<div id="app-container">
    <aside id="sidebar">
        <div class="header">
            <h1>롯데월드타워 설계 개념</h1>
            <div class="model-id">Model: gemma-4-31b-bedrock</div>
        </div>

        <div class="section">
            <h2>1. 설계 기본 제원 (추정치)</h2>
            <p style="font-size: 0.8rem; line-height: 1.5;">
                • 높이: 555m (지상 123층)<br>
                • 컨셉: 한국 도자기의 곡선미<br>
                • 구조: 코어월 + 아웃리거 + 벨트트러스<br>
                <small>* 공개 자료 기반의 개념 재구성치입니다.</small>
            </p>
        </div>

        <div class="section">
            <h2>2. 2D 개념 도면</h2>

            <div class="drawing-label">배치도 (Site Plan - 추정 단위: m)</div>
            <canvas id="canvas-site" class="drawing-canvas"></canvas>

            <div class="drawing-label">기준층 평면도 (Typical Floor - 추정)</div>
            <canvas id="canvas-floor" class="drawing-canvas"></canvas>

            <div class="drawing-label">정면 입면도 (Elevation - H: 555m)</div>
            <canvas id="canvas-elev" class="drawing-canvas"></canvas>

            <div class="drawing-label">단면도 (Section - 구조 개념)</div>
            <canvas id="canvas-sect" class="drawing-canvas"></canvas>
        </div>
    </aside>

    <main id="viewer-container">
        <div id="canvas-3d"></div>
        <div class="legend">
            <b>조작법:</b><br>
            회전: 좌클릭 드래그<br>
            이동: 우클릭 드래그<br>
            확대: 휠 스크롤
        </div>
        <div id="controls">
            <button class="step-btn active" onclick="setStep(0)">Step 1: 매스 분석</button>
            <button class="step-btn" onclick="setStep(1)">Step 2: 곡선 최적화</button>
            <button class="step-btn" onclick="setStep(2)">Step 3: 최종 형상</button>
            <button class="step-btn" onclick="resetView()">시점 초기화</button>
        </div>
    </main>
</div>

<script>
    /**
     * 2D DRAWINGS IMPLEMENTATION
     */
    function drawDiagrams() {
        const site = document.getElementById('canvas-site');
        const floor = document.getElementById('canvas-floor');
        const elev = document.getElementById('canvas-elev');
        const sect = document.getElementById('canvas-sect');

        const ctxS = site.getContext('2d');
        const ctxF = floor.getContext('2d');
        const ctxE = elev.getContext('2d');
        const ctxT = sect.getContext('2d');

        // Site Plan
        ctxS.strokeStyle = '#333';
        ctxS.strokeRect(50, 50, 100, 100); // Site
        ctxS.fillStyle = '#aaa';
        ctxS.beginPath();
        ctxS.arc(100, 100, 15, 0, Math.PI * 2);
        ctxS.fill();
        ctxS.strokeText("Lotte World Tower Site", 60, 40);
        ctxS.strokeText("Scale: Approx 1/2000", 60, 160);

        // Floor Plan
        ctxF.strokeStyle = '#333';
        ctxF.beginPath();
        ctxF.ellipse(100, 100, 40, 40, 0, 0, Math.PI * 2);
        ctxF.stroke();
        ctxF.strokeRect(85, 85, 30, 30); // Core
        ctxF.strokeText("Core Wall", 118, 100);
        ctxF.strokeText("Typical Floor Level", 60, 30);

        // Elevation
        ctxE.strokeStyle = '#333';
        ctxE.beginPath();
        ctxE.moveTo(100, 180);
        ctxE.quadraticCurveTo(100, 50, 110, 20);
        ctxE.lineTo(120, 20);
        ctxE.quadraticCurveTo(130, 50, 130, 180);
        ctxE.stroke();
        ctxE.fillText("555m", 135, 20);
        ctxE.fillText("Ground", 100, 185);

        // Section
        ctxT.strokeStyle = '#333';
        ctxT.beginPath();
        ctxT.moveTo(100, 180);
        ctxT.lineTo(110, 20);
        ctxT.lineTo(120, 20);
        ctxT.lineTo(130, 180);
        ctxT.stroke();
        ctxT.strokeStyle = 'red';
        ctxT.beginPath();
        ctxT.moveTo(112, 150); ctxT.lineTo(118, 150);
        ctxT.moveTo(112, 100); ctxT.lineTo(118, 100);
        ctxT.stroke();
        ctxT.fillStyle = 'red';
        ctxT.fillText("Outrigger", 125, 100);
    }

    /**
     * 3D VISUALIZATION IMPLEMENTATION
     */
    let scene, camera, renderer, tower, orbitControls;
    let currentStep = 0;

    function init3D() {
        scene = new THREE.Scene();
        scene.background = new THREE.Color(0xeeeeee);

        camera = new THREE.PerspectiveCamera(75, (window.innerWidth - 400) / window.innerHeight, 0.1, 2000);
        camera.position.set(200, 300, 500);

        renderer = new THREE.WebGLRenderer({ antialias: true });
        renderer.setSize(window.innerWidth - 400, window.innerHeight);
        document.getElementById('canvas-3d').appendChild(renderer.domElement);

        const ambientLight = new THREE.AmbientLight(0xffffff, 0.6);
        scene.add(ambientLight);

        const directionalLight = new THREE.DirectionalLight(0xffffff, 0.8);
        directionalLight.position.set(100, 500, 100);
        scene.add(directionalLight);

        // Ground Plane
        const grid = new THREE.GridHelper(1000, 20, 0xcccccc, 0xdddddd);
        scene.add(grid);

        // OrbitControls Implementation
        // Since OrbitControls might be in the external runtime, we check or provide a basic implementation
        if (THREE.OrbitControls) {
            orbitControls = new THREE.OrbitControls(camera, renderer.domElement);
        } else {
            // Basic manual rotation if OrbitControls isn't loaded from the provided runtime
            setupManualControls();
        }

        createTower(0);
        animate();
    }

    function createTower(step) {
        if (tower) scene.remove(tower);

        tower = new THREE.Group();
        const material = new THREE.MeshPhongMaterial({ 
            color: 0xd1dceb, 
            flatShading: false, 
            transparent: true, 
            opacity: 0.9,
            shininess: 100
        });

        const height = 555;
        const baseRadius = 40;
        const topRadius = 15;
        const segments = 32;

        if (step === 0) {
            // STEP 1: Basic Cylinder Mass
            const geom = new THREE.CylinderGeometry(baseRadius, topRadius, height, segments);
            const mesh = new THREE.Mesh(geom, material);
            mesh.position.y = height / 2;
            tower.add(mesh);
        } else if (step === 1) {
            // STEP 2: Curved Tapering (Approximate with Lathe or custom geometry)
            const points = [];
            for (let i = 0; i <= 20; i++) {
                const y = (i / 20) * height;
                const r = baseRadius - (baseRadius - topRadius) * Math.pow(i / 20, 1.5);
                points.push(new THREE.Vector2(r, y));
            }
            const geom = new THREE.LatheGeometry(points, segments);
            const mesh = new THREE.Mesh(geom, material);
            tower.add(mesh);
        } else {
            // STEP 3: Final Shape with Split Detail
            const points = [];
            for (let i = 0; i <= 30; i++) {
                const y = (i / 30) * height;
                const r = baseRadius - (baseRadius - topRadius) * Math.pow(i / 30, 1.8);
                points.push(new THREE.Vector2(r, y));
            }
            const geom = new THREE.LatheGeometry(points, segments);
            const mesh = new THREE.Mesh(geom, material);

            // Adding some "vertical lines" to represent the split facades
            const lineGeom = new THREE.CylinderGeometry(0.5, 0.5, height, 8);
            const lineMat = new THREE.MeshBasicMaterial({color: 0xaaaaaa});
            for(let j=0; j<4; j++) {
                const line = new THREE.Mesh(lineGeom, lineMat);
                const angle = (j / 4) * Math.PI * 2;
                line.position.set(Math.cos(angle)*30, height/2, Math.sin(angle)*30);
                tower.add(line);
            }

            tower.add(mesh);
        }

        scene.add(tower);
    }

    function setStep(step) {
        currentStep = step;
        const btns = document.querySelectorAll('.step-btn');
        btns.forEach((btn, idx) => {
            if(idx < 3) btn.classList.toggle('active', idx === step);
        });
        createTower(step);
    }

    function resetView() {
        camera.position.set(200, 300, 500);
        camera.lookAt(0, 200, 0);
        if(orbitControls) orbitControls.update();
    }

    function setupManualControls() {
        // Minimal orbit logic if the runtime script is missing
        let isDragging = false;
        let prevX, prevY;
        window.addEventListener('mousedown', (e) => { if(e.target.id === 'canvas-3d') isDragging = true; prevX = e.clientX; prevY = e.clientY; });
        window.addEventListener('mouseup', () => isDragging = false);
        window.addEventListener('mousemove', (e) => {
            if (!isDragging) return;
            const dx = e.clientX - prevX;
            const dy = e.clientY - prevY;
            tower.rotation.y += dx * 0.01;
            prevX = e.clientX; prevY = e.clientY;
        });
    }

    function animate() {
        requestAnimationFrame(animate);
        if (orbitControls) orbitControls.update();
        renderer.render(scene, camera);
    }

    window.addEventListener('resize', () => {
        camera.aspect = (window.innerWidth - 400) / window.innerHeight;
        camera.updateProjectionMatrix();
        renderer.setSize(window.innerWidth - 400, window.innerHeight);
    });

    // Entry Point
    window.onload = () => {
        drawDiagrams();
        init3D();
    };
</script>

<!-- Inject OrbitControls from CDN as a fallback if the local runtime is not present -->
<script src="https://cdn.jsdelivr.net/npm/three@0.160.0/examples/js/controls/OrbitControls.js"></script>
</body>
</html>
